const expectedWebhookToken = String($env.PROMO_PAGE_GENERATION_WEBHOOK_TOKEN || '').trim();
const suppliedWebhookToken = String($json.headers?.['x-promo-generation-token'] || '').trim();
if (expectedWebhookToken.length < 32) throw new Error('PROMO_PAGE_GENERATION_WEBHOOK_TOKEN is not configured');
let tokenMismatch = suppliedWebhookToken.length !== expectedWebhookToken.length ? 1 : 0;
const comparisonLength = Math.max(suppliedWebhookToken.length, expectedWebhookToken.length);
for (let index = 0; index < comparisonLength; index += 1) {
  tokenMismatch |= (suppliedWebhookToken.charCodeAt(index) || 0) ^ (expectedWebhookToken.charCodeAt(index) || 0);
}
if (tokenMismatch !== 0) throw new Error('Valid promo generation webhook authentication is required');

const body = $json.body || $json;
const id = String(body.id || ('promo-ai-' + Date.now())).trim();
const md = body.md || {};
const promo = body.promo || {};
const design = body.design || {};
const output = body.output || {};
const n8nWebhookUrl = String(body.n8nWebhookUrl || body.n8n_webhook_url || '').trim();

const requiredPromo = ['title', 'market', 'leadText', 'ctaLabel', 'ctaUrl', 'subline', 'termsText'];
const missingPromo = requiredPromo.filter((key) => !String(promo[key] || '').trim());
if (missingPromo.length) throw new Error('Missing promo fields: ' + missingPromo.join(', '));
if (!/^(https?:\/\/|\/(?!\/)|#[a-z0-9_-]+$)/i.test(String(promo.ctaUrl || '').trim())) throw new Error('promo.ctaUrl must be an approved http(s), root-relative, or fragment URL');
if (!md.brand) throw new Error('md.brand is required');
if (!md.designConcept && !md.designPromptContext) throw new Error('md.designConcept or md.designPromptContext is required');

const concept = md.designConcept || {};
const conceptJson = concept.json || {};
const promptContext = md.designPromptContext || concept.promptContext || '';
const summary = md.summary || {};
const promptVariables = {
  brand: md.brand || '',
  slug: md.slug || '',
  designConceptSummary: concept.summary || conceptJson.brandConcept || '',
  designPromptContext: promptContext,
  designConceptJson: JSON.stringify(conceptJson, null, 2),
  categories: JSON.stringify(summary.categories || []),
  colors: JSON.stringify(summary.colors || []),
  fonts: JSON.stringify(summary.fonts || []),
  promoJson: JSON.stringify(promo, null, 2),
  designJson: JSON.stringify(design, null, 2),
  styleSource: body.styleSource || '',
  styleSourceLabel: body.styleSourceLabel || '',
  companyPreset: JSON.stringify(body.companyPreset || null, null, 2),
  hasOverride: String(Boolean(body.hasOverride))
};
const requiredVisibleCopy = ['title', 'leadText', 'subline', 'ctaLabel', 'termsText']
  .map((key) => String(promo[key] || '').trim())
  .filter(Boolean);
const allowedUrls = Object.entries(promo)
  .filter(([key, value]) => /url/i.test(key) && String(value || '').trim())
  .map(([, value]) => String(value).trim());

return [{
  json: {
    id,
    n8nWebhookUrl,
    md,
    promo,
    design,
    sourceDesign: body.sourceDesign || {},
    styleSource: body.styleSource || '',
    styleSourceLabel: body.styleSourceLabel || '',
    companyPreset: body.companyPreset || null,
    hasOverride: Boolean(body.hasOverride),
    promptVariables,
    requiredVisibleCopy,
    allowedUrls,
    output: {
      format: output.format || 'desktop_web_page',
      viewport: output.viewport || { width: 1440, minWidth: 1180 }
    }
  }
}];

const input = $('Normalize Payload').item.json;
const loadedPrompt = $json;
const renderedPrompt = String(loadedPrompt.renderedPrompt || '').trim();
const model = String(loadedPrompt.model || '').trim();
if (!renderedPrompt || !model) throw new Error('Managed rendered prompt and model are required');
if (String(loadedPrompt.provider || '').toLowerCase() !== 'openai') throw new Error('promo_page_generation requires the managed OpenAI provider');
if (loadedPrompt.promptType !== 'promo_page_generation' || loadedPrompt.promptStatus !== 'active') {
  throw new Error('Active promo_page_generation snapshot is required');
}
const responseFormat = String(loadedPrompt.modelOptions?.responseFormat || loadedPrompt.responseFormat || '').trim();
if (responseFormat !== 'json_object') throw new Error('promo_page_generation responseFormat must be json_object');

const llmRequest = {
  model,
  store: false,
  input: renderedPrompt,
  text: { format: { type: 'json_object' } }
};
const rawTemperature = loadedPrompt.modelOptions?.temperature ?? loadedPrompt.temperature;
const rawMaxTokens = loadedPrompt.modelOptions?.maxTokens ?? loadedPrompt.maxTokens;
const temperature = rawTemperature === null || rawTemperature === undefined || rawTemperature === '' ? null : Number(rawTemperature);
const maxTokens = rawMaxTokens === null || rawMaxTokens === undefined || rawMaxTokens === '' ? null : Number(rawMaxTokens);
if (temperature !== null && Number.isFinite(temperature)) llmRequest.temperature = temperature;
if (maxTokens !== null && Number.isInteger(maxTokens) && maxTokens > 0) llmRequest.max_output_tokens = maxTokens;

return [{
  json: {
    ...input,
    promptMeta: {
      id: loadedPrompt.promptId,
      type: loadedPrompt.promptType,
      name: loadedPrompt.promptName,
      version: loadedPrompt.promptVersion,
      renderedPromptHash: loadedPrompt.renderedPromptHash,
      variableHash: loadedPrompt.variableHash,
      promptLayerSources: loadedPrompt.promptLayerSources || []
    },
    llmRequest
  }
}];

const input = $('Build Page Generation Prompt').item.json;
const response = $json;
const responseOutputText = Array.isArray(response.output)
  ? response.output.flatMap((item) => Array.isArray(item?.content) ? item.content : [])
    .find((item) => item?.type === 'output_text')?.text || ''
  : '';
const content = response.output_text || responseOutputText || response.choices?.[0]?.message?.content || response.message?.content || response.content || response.text || '';
if (!content) throw new Error('LLM response content is empty');
let generated;
try {
  const fence = String.fromCharCode(96, 96, 96);
  generated = typeof content === 'string'
    ? JSON.parse(content.replace(new RegExp('^' + fence + 'json\\s*', 'i'), '').replace(new RegExp(fence + '$', 'i'), '').trim())
    : content;
} catch (error) {
  throw new Error('Failed to parse LLM JSON: ' + error.message);
}
return [{ json: { generated, input } }];

const input = $('Build Page Generation Prompt').item.json;
const artifact = $json;
const browserValidation = $('Browser Quality Gate').item.json;
if (!artifact.ok || !artifact.pagePath || !artifact.contentHash) throw new Error('Generated page artifact was not persisted');
if (browserValidation.browserQualityGate?.state !== 'passed' || Number(browserValidation.browserQualityGate?.blockingCount || 0) !== 0) {
  throw new Error('Generated page browser quality gate is not passed');
}
const artifactEndpoint = String($env.PROMO_PAGE_ARTIFACT_URL || '').trim();
if (!/^https?:\/\//i.test(artifactEndpoint)) throw new Error('PROMO_PAGE_ARTIFACT_URL must be an absolute internal API URL');
const pageUrl = new URL(artifact.pagePath, new URL(artifactEndpoint).origin).toString();
const { llmRequest, promptVariables, requiredVisibleCopy, allowedUrls, n8nWebhookUrl, ...safeInput } = input;
return [{
  json: {
    ok: true,
    id: artifact.id,
    pageUrl,
    pagePath: artifact.pagePath,
    contentHash: artifact.contentHash,
    expiresAt: artifact.expiresAt,
    promptMeta: input.promptMeta,
    browserQualityGate: browserValidation.browserQualityGate,
    payload: safeInput
  }
}];
